selector_to_html = {"a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"results/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.results<a class=\"headerlink\" href=\"#module-pyskyfire.common.results\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.common\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common<a class=\"headerlink\" href=\"#module-pyskyfire.common\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"constants/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.constants<a class=\"headerlink\" href=\"#module-pyskyfire.common.constants\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"momentum/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.momentum<a class=\"headerlink\" href=\"#module-pyskyfire.common.momentum\" title=\"Link to this heading\">\u00b6</a></h1><p>One-dimensional static-pressure changes shared by heated duct solvers.</p>", "a[href=\"solids/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.solids<a class=\"headerlink\" href=\"#module-pyskyfire.common.solids\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"blade_surface/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.blade_surface<a class=\"headerlink\" href=\"#module-pyskyfire.common.blade_surface\" title=\"Link to this heading\">\u00b6</a></h1><p>Blade surfaces in cylindrical coordinates, shared by impellers and turbines.</p><p>A blade is two sides, suction and pressure, each an array of shape\n<code class=\"docutils literal notranslate\"><span class=\"pre\">(span,</span> <span class=\"pre\">chord,</span> <span class=\"pre\">3)</span></code> in <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r,</span> <span class=\"pre\">theta)</span></code>: metres, metres, radians, about the\nshaft (+x). The sides meet at the leading and trailing edges, so their first\nand last chord stations coincide.</p>", "a[href=\"rotation/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.rotation<a class=\"headerlink\" href=\"#module-pyskyfire.common.rotation\" title=\"Link to this heading\">\u00b6</a></h1><p>Sense of rotation about a component\u2019s own axis.</p><p>An impeller spins one way about its shaft and the volute around it must wind\nthe same way, since a volute wound against the discharge swirl collects the\nflow backwards. Both state the sense with the same word here, so that a design\ncan be checked by reading it rather than by looking at a render.</p>", "a[href=\"meridional/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.meridional<a class=\"headerlink\" href=\"#module-pyskyfire.common.meridional\" title=\"Link to this heading\">\u00b6</a></h1><p>The wetted flow path of a turbomachine or annular duct, seen in meridional section.</p><p>A passage is two walls of revolution about the shaft (+x), each given as an\n<code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> curve: the <code class=\"docutils literal notranslate\"><span class=\"pre\">hub</span></code> nearer the axis and the <code class=\"docutils literal notranslate\"><span class=\"pre\">shroud</span></code> outside it.\nBoth curves have the same number of points, and point <code class=\"docutils literal notranslate\"><span class=\"pre\">i</span></code> on one pairs with\npoint <code class=\"docutils literal notranslate\"><span class=\"pre\">i</span></code> on the other. Each pair is the end of a span line, and positions\nalong the passage are fractions of the hub\u2019s arc length. That pairing is what\nlets blade sections be placed at a span fraction, and what an annular duct\nreads its area from.</p>", "a[href=\"friction/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.friction<a class=\"headerlink\" href=\"#module-pyskyfire.common.friction\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct friction physics shared by cooling channels and piping.</p><p>This module is deliberately geometry-agnostic. Every entry point takes plain\nscalars \u2013 a Reynolds number, a hydraulic diameter, an absolute roughness, a\nsigned radius of curvature \u2013 so the same physics serves a regen cooling\nchannel marching on an axial coordinate and a pipe run marching on arc length.\nAnything that knows about contours, centerlines or stations belongs elsewhere.</p>", "a[href=\"physics/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.physics<a class=\"headerlink\" href=\"#module-pyskyfire.common.physics\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"section_geometry/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.section_geometry<a class=\"headerlink\" href=\"#module-pyskyfire.common.section_geometry\" title=\"Link to this heading\">\u00b6</a></h1><p>Planar arc geometry used by section analytics and physical construction.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
